#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    vector<int> addToArrayForm(vector<int>& A, int K) {
        int n = A.size();
        vector<int> result;

        while (K > 0 || n > 0) {
            if (n > 0) K += A[--n];
            result.push_back(K % 10);
            K /= 10;
        }

        reverse(result.begin(), result.end());
        return result;
    }
};
